<!-- eslint-disable @typescript-eslint/no-explicit-any, @stylistic/brace-style -->
<template>
  <v-container><UiPageHeader title="Quests" subtitle="Campaign quest library"><template #actions><v-btn data-testid="quest-add" color="primary" @click="add">Add quest</v-btn></template></UiPageHeader><v-alert v-if="!campaignId" type="info">Choose a campaign first.</v-alert><v-row v-else><v-col cols="12" md="4"><v-list><v-list-item v-for="quest in quests" :key="quest.id" :data-testid="`quest-${quest.title}`" :active="selected?.id === quest.id" :title="quest.title" :subtitle="quest.status" @click="selected = { ...quest }" /></v-list></v-col><v-col cols="12" md="8"><v-card v-if="selected"><v-card-title class="d-flex"><v-text-field v-model="selected.title" data-testid="quest-title" label="Title" @blur="save" /><v-btn data-testid="quest-delete" color="error" variant="text" class="ml-2" @click="requestDelete">Delete</v-btn></v-card-title><v-card-text><v-select v-model="selected.status" :items="statuses" label="Status" @update:model-value="save" /><v-textarea v-model="selected.description" label="Description" @blur="save" /><v-textarea v-model="selected.recovery_notes" label="Recovery / convergence notes" @blur="save" /><v-divider class="my-4" /><h3>Story links</h3><v-select v-model="linkedNpcUids" :items="linkData.npcs" item-title="name" item-value="uid" label="NPCs" multiple chips closable-chips data-testid="quest-npc-links" @update:model-value="saveLinks" /><v-select v-model="linkedDialogueIds" :items="linkData.dialogues" item-title="title" item-value="id" label="Dialogues" multiple chips closable-chips data-testid="quest-dialogue-links" @update:model-value="saveLinks" /><div class="d-flex align-center"><h3>Objectives</h3><v-spacer /><v-btn data-testid="quest-add-objective" size="small" @click="addObjective">Add objective</v-btn></div><v-list><v-list-item v-for="objective in objectives" :key="objective.id" :data-testid="`quest-objective-${objective.title}`"><v-text-field v-model="objective.title" density="compact" hide-details @blur="saveObjective(objective)" /><template #append><v-select v-model="objective.status" density="compact" hide-details :items="['pending', 'active', 'completed', 'failed']" style="width: 120px" @update:model-value="saveObjective(objective)" /><v-btn data-testid="quest-objective-delete" aria-label="Delete objective" icon="mdi-delete" size="small" variant="text" @click="removeObjective(objective)" /></template></v-list-item></v-list><v-divider class="my-4" /><div class="d-flex align-center"><h3>State transitions</h3><v-spacer /><v-btn data-testid="quest-add-transition" size="small" @click="addTransition">Add transition</v-btn></div><v-list density="compact"><v-list-item v-for="transition in transitions" :key="transition.id" :title="`${transition.from_status} → ${transition.to_status}`" :subtitle="transition.condition_ast" /></v-list><div class="d-flex align-center"><h3>Dependencies</h3><v-spacer /><v-btn data-testid="quest-add-dependency" size="small" @click="addDependency">Add dependency</v-btn></div><v-chip v-for="dependency in dependencies" :key="dependency.id" class="ma-1">{{ dependency.title }}</v-chip><v-btn data-testid="quest-validate" class="mt-4" variant="tonal" @click="validate">Validate</v-btn><v-alert v-if="errors.length" type="warning" class="mt-2">{{ errors.join(', ') }}</v-alert><v-alert v-else-if="validated" type="success" class="mt-2">No quest validation issues.</v-alert></v-card-text></v-card></v-col></v-row><UiDeleteConfirmDialog v-model="showDeleteDialog" title="Delete quest" :message="`Delete '${selected?.title}' and all its objectives?`" :loading="deleting" @confirm="confirmDelete" @cancel="showDeleteDialog = false" /></v-container>
</template>

<script setup lang="ts">
/* eslint-disable @typescript-eslint/no-explicit-any, @stylistic/brace-style */
const campaign = useCampaignStore(); const campaignId = computed(() => campaign.activeCampaignIdNumber); const statuses = ['draft', 'available', 'active', 'completed', 'failed']; const { data: quests, refresh } = await useAsyncData(() => campaignId.value ? $fetch<any[]>(`/api/campaigns/${campaignId.value}/quests`) : Promise.resolve([]), { watch: [campaignId] }); const selected = ref<any>(null); const errors = ref<string[]>([]); const validated = ref(false); const showDeleteDialog = ref(false); const deleting = ref(false); const linkData = ref<any>({ npcs: [], dialogues: [] }); const linkedNpcUids = ref<string[]>([]); const linkedDialogueIds = ref<number[]>([]); const path = computed(() => campaignId.value && selected.value ? `/api/campaigns/${campaignId.value}/quests/${selected.value.id}` : ''); const { data: objectives, refresh: refreshObjectives } = await useAsyncData(() => path.value ? $fetch<any[]>(`${path.value}/objectives`) : Promise.resolve([]), { watch: [path] }); const { data: transitions, refresh: refreshTransitions } = await useAsyncData(() => path.value ? $fetch<any[]>(`${path.value}/transitions`) : Promise.resolve([]), { watch: [path] }); const { data: dependencies, refresh: refreshDependencies } = await useAsyncData(() => path.value ? $fetch<any[]>(`${path.value}/dependencies`) : Promise.resolve([]), { watch: [path] }); watch(path, async (value) => { if (!value) return; const result = await $fetch<any>(`${value}/links`); linkData.value = result; linkedNpcUids.value = result.npc_uids; linkedDialogueIds.value = result.dialogue_ids }, { immediate: true }); async function saveLinks() { if (path.value) await $fetch(`${path.value}/links`, { method: 'PUT', body: { npc_uids: linkedNpcUids.value, dialogue_ids: linkedDialogueIds.value } }) } async function add() { if (!campaignId.value) return; const title = prompt('Quest title'); if (!title) return; selected.value = await $fetch(`/api/campaigns/${campaignId.value}/quests`, { method: 'POST', body: { title } }); await refresh() } function requestDelete() { if (selected.value) showDeleteDialog.value = true } async function confirmDelete() { if (!path.value) return; deleting.value = true; try { await $fetch(path.value, { method: 'DELETE' }); showDeleteDialog.value = false; selected.value = null; await refresh() } finally { deleting.value = false } } async function save() { if (path.value) { await $fetch(path.value, { method: 'PATCH', body: selected.value }); await refresh() } } async function addObjective() { const title = prompt('Objective title'); if (title && path.value) { await $fetch(`${path.value}/objectives`, { method: 'POST', body: { title } }); await refreshObjectives() } } async function saveObjective(objective: any) { if (path.value) await $fetch(`${path.value}/objectives/${objective.id}`, { method: 'PATCH', body: objective }) } async function removeObjective(objective: any) { if (path.value) { await $fetch(`${path.value}/objectives/${objective.id}`, { method: 'DELETE' }); await refreshObjectives() } } async function addTransition() { if (!path.value) return; const from_status = prompt('From status', 'available'); const to_status = prompt('To status', 'active'); if (from_status && to_status) { await $fetch(`${path.value}/transitions`, { method: 'POST', body: { from_status, to_status } }); await refreshTransitions() } } async function addDependency() { if (!path.value) return; const id = prompt('Quest ID to depend on'); if (id) { await $fetch(`${path.value}/dependencies`, { method: 'POST', body: { depends_on_quest_id: Number(id) } }); await refreshDependencies() } } async function validate() { if (path.value) { errors.value = (await $fetch<{ errors: string[] }>(`${path.value}/validate`)).errors; validated.value = true } }
</script>
